const ITEM_TIPS: Record<string, string> = {"I00L": "+200 Mana\n|cff5ddf26Equip: Reduces the cooldowns of all abilities by 1,5 seconds.|r\n|cff5ddf26Equip: Your spellcasts have 15% chance to stun you for 2 seconds.|r\n|cffeccf11\"Pass it around.\"|r", "I029": "+7 Potency\n+8% Haste\n|cff5ddf26Equip: Shoots an arcane blast that deals 20 |r|cff83d5fcspell|r|cff5ddf26 damage at a random nearby enemy unit every 0,50 seconds.|r", "I02K": "+25 All Stats\n+15 Health per second\n|cff5ddf26Equip: Your Health Regeneration inflicts |r|cff83d5fcSpell|r|cff5ddf26 damage to your Hero instead of restoring health. Health Regeneration now only works during combat.|r", "I02P": "+7 Potency\n+150 Mana\n|cff5ddf26Use: Summons a nerubian warrior to fight by your side for 35 seconds. (80 seconds cooldown)|r\n|cffeccf11\"A magical staff that was used to repel intruders that tried to enter the underground kingdom by shooting magic blasts at them.\"|r", "I03C": "+10 to Primary Attribute\n+8 Mana per 5 seconds\n+5 Health per second\n|cff5ddf26Equip: Reduces the cooldowns of all abilities by 0,5 seconds.|r", "I041": "+8 All Stats\n+8% Haste\n+6 Health per second\n|cff5ddf26Equip: Dealing damage from any source has |r|cff33937f2,5%|r|cff5ddf26 chance to send forth a Carrion Swarm that deals Attrition damage equal to 75% of All Stats to enemies it passes through.|r", "I048": "|cff87ceebBinds to Player|r\n+20 to Primary Attribute\n+10 Mastery\n+250 Mana\n|cff5ddf26Equip: Increases the damage dealt by Magical Type effects by 20%.|r\n|cff5ddf26Equip: Your abilities have their base cooldown reduced by 13%.|r", "I04J": "|cffff8c00Magical Caster Relic|r\n+12 Primary Attribute\n+15% Haste\n|cff5ddf26Equip: Increases the damage dealt by Magical Type effects by 10%.|r\n|cff5ddf26Equip: Every 3rd Magical Type spellcast fires a massive bolt of Arcane Energy at the closest non-Lesser Creature enemy, dealing damage equal to 20% of Primary Attribute for each second of the total base cooldown of the 3 spells that were cast. Spells  benefit from this effect at 10% effectiveness while having Glyph of Arc Striking. This is a Magical Type effect.|r", "I05X": "+32% Attack Speed\n+18% Haste\n+8 Potency", "I06M": "+12 to Primary Attribute\n+10 Mana per 5 seconds\n+14% Spell Damage Reduction\n|cff5ddf26Equip: Grants nearby allied heroes Arcane Aura, which increases Haste by 12%. Auras with the same name do not stack. This effect is 50% weaker on your own hero.|r", "I07F": "+10 to Primary Attribute\n+9 Mana per 5 seconds\n+5 Potency\n|cff5ddf26Equip: Increases the damage dealt by Magical Type effects by 13%.|r\n|cff5ddf26Equip: Siphons energy from the spellcasts of allied Heroes to trigger an electric discharge, dealing 10 plus additional 40% of Primary Attribute Magical Type damage to enemies within 400 range.|r", "I07O": "+15% Attack Speed\n+10% Haste\n+6 All Stats\n|cff5ddf26Use: Switches between 1 of 3 Orb Powers. (Cooldown: 5 seconds)\nFire: Attacks splash for 20 damage and additional 35% of Primary Attribute.|r\n|cffa7a7a4Frost: Attacks Chill the target, reducing its movement speed by 50% and its attack speed by 25% for 4 seconds.|r\n|cffa7a7a4Shadow: Attacks ignore 6 of the target's Armor.|r", "I08T": "+10 to Primary Attribute\n+12% Haste\n+14% Spell Damage Reduction\n|cff5ddf26Equip: Allows you to benefit from Glyph of Renewal and Glyph of Thunder.|r", "I096": "+12% Haste\n+12% Spell Damage Reduction\n+12 Mana per 5 seconds\n|cff5ddf26Equip: Reduces the cooldowns of all abilities by 0,5 seconds.|r\n|cff5ddf26Equip: Your spellcasts refund 15% of their mana cost.|r", "I0BR": "|cff87ceebBinds to Player|r\n+20 to Primary Attribute\n+28% Attack Speed\n+10 Mastery\n|cff5ddf26Equip: Your attacks have |r|cff33937f10%|r|cff5ddf26 chance to strike an additional time.|r\n|cff5ddf26Equip: Whenever you cast a spell, you ignite your weapon, causing your next attack to splash for amount equal to 100% of your Primary Attribute. This is a Magical Type effect.|r", "I0C2": "+15 All Stats\n+15 Mastery\n+12% Haste", "I0C9": "+5 All Stats\n+6 Mastery\n+7% Haste\n+12 Damage\n+3 Armor\n+3 Potency\n+65 Mana\n|cffeccf11\"The relics of Ahn'Quiraj are rumoured to have been touched by C'thun itself.\"|r", "I0DF": "+13 to Primary Attribute\n+13% Haste\n|cffeccf11\"Produces a quiet hum when placed on the finger.\"|r", "I0F9": "|cff36bcc1Unique|r\n+7 All Stats\n+7% Haste\n|cff5ddf26Use: Equips nearby allies with Pirate Hats for 10 seconds, increasing their damage by 20% and causing them to regenerate 3 health per second. (Cooldown: 35 seconds)|r", "I0FU": "+12 to Primary Attribute\n+8% Attack Speed\n|cff5ddf26Equip: Increases the damage dealt by Magical Type effects by 12%.|r\n|cff5ddf26Equip: Grants you and nearby allies Brilliance Aura, which provides 4 mana per 5 seconds. Auras with the same name do not stack.|r", "I0FW": "+55 to Primary Attribute\n|cff5ddf26Equip: Increases the cooldown of all abilities by 12%. This effect stacks additively.|r", "I0HZ": "+8 to Primary Attribute\n+5 Potency\n+20 Movement Speed\n|cff5ddf26Equip: Increases all damage dealt by 12% while moving. This is a multiplicative increase.|r", "I0IK": "+10 to Primary Attribute\n+8% Haste\n+8% Luck\n|cff5ddf26Use: Toggles between Magical and Physical modifier for this item's effect. (Cooldown: 5 seconds)|r\n|cff5ddf26Equip: Increases the damage dealt by Glyphs of Hellfire, Blood Violence and Thunder by 50% and their damage is now classified as Magical or Physical.|r", "I0J5": "+10 Strength\n+10% Haste\n+100 Health\n|cff5ddf26Equip: Causes you to restore 10% of any damage dealt.|r", "I0JO": "|cffff8c00Magical Caster Relic|r\n+16 to Primary Attribute\n+10 Mastery\n|cff5ddf26Equip: Increases the damage dealt by Magical Type effects by 30%.|r\n|cff5ddf26Equip: Increases your base attack cooldown by 20%.|r", "I0NI": "|cffff8c00Battlecaster Relic|r\n+10 to Primary Attribute\n+16% Attack Speed\n+8 Mastery\n|cff5ddf26Equip: Increases the damage dealt by Magical Type effects by 12%.|r\n|cff5ddf26Equip: Your attacks have |r|cff33937f20%|r|cff5ddf26 chance to cause 40 damage plus 150% of Primary Attribute. After casting your \"Q\" ability the proc chance will be 100% and the damage dealt will be increased by 20%. This is a Magical Type effect.|r", "I0NT": "+15% Attack Speed\n+10% Haste\n+6 All Stats\n|cff5ddf26Use: Switches between 1 of 3 Orb Powers. (Cooldown: 5 seconds)\nFire: Attacks splash for 20 damage and additional 35% of Primary Attribute.|r\n|cffa7a7a4Frost: Attacks Chill the target, reducing its movement speed by 50% and its attack speed by 25% for 4 seconds.|r\n|cffa7a7a4Shadow: Attacks ignore 6 of the target's Armor.|r", "I0ON": "+10 to Primary Attribute\n+180 Health\n+10% Haste\n|cff5ddf26Equip: Your Basic Attacks have 15% chance to Stun your opponent for 1 second.|r\n|cff5ddf26Use: Upgrades a targeted allied non-ward unit, permanently giving it 25% Attack Speed and 12% reduced damage taken from all sources. If the target is a non-Hero unit, any units spawned of the same type will also gain this buff. Only 1 type of unit can be affected at a time. (Cooldown: 60 seconds)|r", "I0QT": "+14 to Primary Attribute\n+9 Damage\n+4 Armor\n|cff5ddf26Equip: Increases your Magical and Physical Type effectiveness by 13%, increased by an additional amount up to 25% based on the target's current Health.|r\n|cff5ddf26Equip: Increases the base cooldown of all abilities by 10%. This effect stacks additively.|r", "I0R0": "+12 Strength\n+10% Haste\nClasses: |cfff58cbaPaladin|r\n|cff5ddf26Equip: Allows you to benefit from the Divine Toll Talent.|r", "I0SR": "+12% Haste\n+10% Healing Power\n+8 to Primary Attribute\n|cff5ddf26Equip: Spellcasts restore 25 health to the most wounded nearby Hero, increased by an amount equal to 75% of Primary Attribute. This is a Healing Type effect.|r", "I0TO": "+10% Haste\n+6 All Stats\n|cff5ddf26Equip: Your spellcasts have |r|cff33937f1%|r|cff5ddf26 chance of either killing you or granting you 1 ESC Point.|r", "fgrd": "+12 to Primary Attribute\n+8% Haste\n+6 Agility\n|cff5ddf26Equip: Increases the damage dealt by Magical Type effects by 30%.|r\n|cff5ddf26Equip: Reduces the effectiveness of Healing Type effects on your hero by 30%.|r", "tgrh": "+200 Mana\n-5 Armor\n|cff5ddf26Equip: Increases damage dealt by Magical and Physical Type effects by 20%.|r", "war2": "+30 Strength\n-10 Intelligence\n|cff5ddf26Equip: Your Basic Attacks have 15% chance to Stun your opponent for 1 second.|r\n|cffeccf11\"You don't need lots of brains to hit hard.\"|r"};

